(gene_list: Union[str, List[str], Tuple[str, ...], pandas.core.series.Series, pandas.core.frame.DataFrame], gene_sets: Union[List[str], str, Dict[str, str]], *, organism: str = 'human', outdir: Optional[str] = None, background: Union[List[str], int, str] = None, cutoff: float = 0.05, format: str = 'pdf', figsize: Tuple[float, float] = (6.5, 6), top_term: int = 10, no_plot: bool = False, verbose: bool = False) -> gseapy.enrichr.Enrichr
    def get_results(self, gene_list: str, gene_set_libraries: List[str]) -> Tuple[str, pd.DataFrame]:
        """Get enrichment results from Enrichr API."""
        payload = {"list": (None, gene_list), "description": (None, self.descriptions)}
        job_id = self.send_genes(payload, f"{self.base_url}/addList")

        res = self.get_results_dataframe(job_id["userListId"], gene_set_libraries)
        return (job_id["shortId"], res)

